script:
(function(){
var root=root_element.querySelector('.dsync');if(!root)return;
var method='cannabis_management.api.daily_sync_dashboards.get_sales_daily_sync_dashboard';
function q(sel){return root.querySelector(sel)}
function qa(sel){return Array.prototype.slice.call(root.querySelectorAll(sel))}
function set(name,val){var els=root.querySelectorAll('[data-kpi="'+name+'"]');els.forEach(function(el){el.innerHTML=val;});}
function money(v){v=parseFloat(v||0);if(Math.abs(v)>=1000000)return '$'+(v/1000000).toFixed(1)+'M';if(Math.abs(v)>=1000)return '$'+(v/1000).toFixed(1)+'K';return '$'+v.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:0})}
function num(v,d){return parseFloat(v||0).toLocaleString(undefined,{maximumFractionDigits:d==null?0:d})}
function pct(v){return num(v,1)+'%'}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function fmtDate(d){if(!d)return'—';var p=String(d).split(' ')[0].split('-');return p.length===3?p[1]+'/'+p[2]+'/'+p[0]:d}

function delta(v,suffix,unit){
  v=parseFloat(v||0);
  var up=v>=0;
  var abs=Math.abs(v);
  var label=(unit==='money'?money(abs):num(abs,1))+(suffix||'');
  var arrow=up?'▲':'▼';
  var cls=up?'dsync-delta-up':'dsync-delta-dn';
  return '<span class="dsync-delta '+cls+'">'+(up?arrow+' +':arrow+' -')+label+' vs prior day</span>';
}

function lineChart(el,rows,key,color){
  if(!el)return;
  rows=rows||[];key=key||'value';
  var vals=rows.map(function(r){return parseFloat(r[key]||0)});
  var max=Math.max.apply(null,vals.concat([0]));
  var min=Math.min.apply(null,vals.concat([0]));
  if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data available for this period</div>';return;}
  var w=620,h=150,p=24,span=Math.max(max-min,1);
  var pts=vals.map(function(v,i){
    var x=p+(i*(w-2*p)/Math.max(vals.length-1,1));
    var y=h-p-((v-min)/span*(h-2*p));
    return[x,y];
  });
  var d=pts.map(function(pt,i){return(i?'L':'M')+pt[0].toFixed(1)+' '+pt[1].toFixed(1)}).join(' ');
  var area=d+' L '+pts[pts.length-1][0]+' '+(h-p)+' L '+pts[0][0]+' '+(h-p)+' Z';
  // X-axis date labels (first, middle, last)
  var labels='';
  if(rows.length>=2){
    var positions=[0,Math.floor(rows.length/2),rows.length-1];
    positions.forEach(function(i){
      var pt=pts[i];
      var lbl=rows[i]?fmtDate(rows[i].date):'—';
      labels+='<text x="'+pt[0].toFixed(1)+'" y="'+(h-4)+'" text-anchor="middle" class="dsync-chart-lbl">'+esc(lbl)+'</text>';
    });
  }
  // Dots on last value
  var lastPt=pts[pts.length-1];
  var lastVal=vals[vals.length-1];
  var tooltip=rows[rows.length-1]?fmtDate(rows[rows.length-1].date)+': '+num(lastVal,0):'—';
  el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'
    +'<defs><linearGradient id="cg_'+color.replace(/[^a-z0-9]/gi,'')+'" x1="0" y1="0" x2="0" y2="1">'
    +'<stop offset="0%" stop-color="'+color+'" stop-opacity="0.18"/>'
    +'<stop offset="100%" stop-color="'+color+'" stop-opacity="0.02"/>'
    +'</linearGradient></defs>'
    +'<path class="dsync-fill" fill="url(#cg_'+color.replace(/[^a-z0-9]/gi,'')+')" d="'+area+'"></path>'
    +'<path class="dsync-line" style="stroke:'+color+'" d="'+d+'"></path>'
    +'<circle cx="'+lastPt[0].toFixed(1)+'" cy="'+lastPt[1].toFixed(1)+'" r="4" fill="'+color+'" stroke="#fff" stroke-width="2"><title>'+esc(tooltip)+'</title></circle>'
    +'<line class="dsync-axis" x1="'+p+'" y1="'+(h-p+4)+'" x2="'+(w-p)+'" y2="'+(h-p+4)+'"></line>'
    +labels+'</svg>';
}

function table(headers,rows,badges){
  if(!rows||!rows.length)return '<div class="dsync-empty">No data found.</div>';
  return '<table><thead><tr>'+headers.map(function(h){return'<th>'+esc(h.label)+'</th>'}).join('')+'</tr></thead>'
    +'<tbody>'+rows.map(function(r){return'<tr>'+headers.map(function(h){return'<td>'+h.f(r)+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table>';
}

function renderSales(d){
  var s=d.summary||{},c=d.crm||{};
  set('cod_count','<span class="dsync-big-num">'+num(s.cod_unpaid_count)+'</span>');
  set('cod_count_delta',delta(s.cod_count_delta,''));
  set('cod_amount','<span class="dsync-big-num">'+money(s.cod_unpaid_amount)+'</span>');
  set('cod_amount_delta',delta(s.cod_amount_delta,'','money'));
  var acc=parseFloat(s.prediction_accuracy||0);
  var accCls=acc>=90?'dsync-pct-green':acc>=70?'dsync-pct-amber':'dsync-pct-red';
  set('prediction_accuracy','<span class="dsync-big-num '+accCls+'">'+pct(acc)+'</span>');
  set('prediction_totals','<span class="dsync-kpi-detail">'+money(s.prediction_received)+' received &middot; '+money(s.prediction_expected)+' invoiced</span>');
  var tpct=parseFloat(s.sales_target_pct||0);
  var tCls=tpct>=100?'dsync-pct-green':tpct>=70?'dsync-pct-amber':'dsync-pct-red';
  set('target_pct','<span class="dsync-big-num '+tCls+'">'+pct(tpct)+'</span>');
  set('target_totals','<span class="dsync-kpi-detail">'+money(s.sales_month_actual)+' actual &middot; '+money(s.sales_month_target)+' target</span>');
  set('crm_leads','<span class="dsync-metric-num">'+num(c.total_leads)+'</span>');
  set('crm_open','<span class="dsync-metric-num">'+num(c.ongoing_deals)+'</span>');
  set('crm_won','<span class="dsync-metric-num">'+num(c.won_deals)+'</span>');
  set('crm_conversion','<span class="dsync-metric-num">'+pct(c.conversion_pct)+'</span>');
  // date range label
  var p=d.period||{};
  var dateRange=p.from_date?fmtDate(p.from_date)+' – '+fmtDate(p.to_date):'Last 14 days';
  set('ar_date_range',dateRange);
  set('unrec_date_range',dateRange);
  lineChart(q('[data-chart="ar"]'),s.ar_trend,'value','#401090');
  lineChart(q('[data-chart="unreconciled"]'),s.unreconciled_trend,'value','#dc3545');
  // AR badge — last value
  var arTrend=s.ar_trend||[];
  if(arTrend.length){var el=q('#dsync-ar-badge');if(el)el.textContent=money(arTrend[arTrend.length-1].value||0);}
  var unTrend=s.unreconciled_trend||[];
  if(unTrend.length){var el2=q('#dsync-unrec-badge');if(el2)el2.textContent=num(unTrend[unTrend.length-1].value||0)+' accounts';}
  var cashRows=d.cash_bank_rows||[];
  var cashEl=q('[data-table="cash"]');
  if(cashEl){
    cashEl.innerHTML=table([
      {label:'Date',f:function(r){return'<span class="dsync-date">'+esc(fmtDate(r.date))+'</span>'}},
      {label:'Type',f:function(r){return'<span class="dsync-badge-type">'+esc(r.type||'Payment')+'</span>'}},
      {label:'Amount',f:function(r){return'<span class="dsync-money">'+money(r.amount)+'</span>'}}
    ],cashRows);
    var cb=q('#dsync-cash-count');if(cb)cb.textContent=cashRows.length+' entries';
  }
  var outRows=d.outstanding_accounts||[];
  var outEl=q('[data-table="outstanding"]');
  if(outEl){
    outEl.innerHTML=table([
      {label:'Customer',f:function(r){return'<span class="dsync-cust">'+esc(r.customer)+'</span>'}},
      {label:'Outstanding',f:function(r){return'<span class="dsync-money dsync-money-warn">'+money(r.amount)+'</span>'}},
      {label:'Days Overdue',f:function(r){
        var days=parseInt(r.days_overdue||0);
        var cls=days>30?'dsync-badge-red':days>7?'dsync-badge-amber':'dsync-badge-ok';
        return'<span class="dsync-badge-days '+cls+'">'+days+' days</span>';
      }}
    ],outRows);
    var ob=q('#dsync-out-count');if(ob)ob.textContent=outRows.length+' customers';
  }
}

function load(){
  qa('[data-kpi]').forEach(function(el){
    if(!el.innerHTML||el.innerHTML==='—'||el.innerHTML.indexOf('dsync-shimmer')!==-1){
      el.innerHTML='<span class="dsync-shimmer"></span>';
    }
  });
  frappe.call({
    method:method,
    callback:function(r){var d=r.message||{};renderSales(d);set('last_refresh',new Date().toLocaleTimeString());},
    error:function(){frappe.msgprint('Unable to load Sales Daily Sync data.');}
  });
}

var btn=q('[data-action="refresh"]');
if(btn)btn.addEventListener('click',load);
load();
setInterval(load,30*60*1000);
})();

style:
.dsync{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:1600px;margin:0 auto;padding:24px;color:#1e293b}.dsync *{box-sizing:border-box}

/* ── Header ── */
.dsync-header{background:linear-gradient(135deg,#401090 0%,#7c3aed 60%,#C060E0 100%);color:#fff;border-radius:12px;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:16px}
.dsync-header-left{display:flex;align-items:center;gap:16px}
.dsync-header-right{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.dsync-last-refresh{font-size:11px;color:rgba(255,255,255,.7);font-family:Consolas,'Courier New',monospace}
.dsync-header h2{font-size:20px;margin:0 0 2px;font-weight:800;letter-spacing:-.3px;color:#fff;}
.dsync-header p{margin:0;font-size:11.5px;opacity:.82}
.dsync-eyebrow{font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;opacity:.75;margin-bottom:3px}
.dsync-logo{width:48px;height:48px;border-radius:10px;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center;font-weight:900;font-size:16px;flex-shrink:0}
.dsync-refresh{display:inline-flex;align-items:center;gap:6px;border:1px solid rgba(255,255,255,.4);background:rgba(255,255,255,.15);color:#fff;border-radius:8px;padding:8px 14px;font-size:12px;font-weight:700;cursor:pointer;transition:background .15s}
.dsync-refresh:hover{background:rgba(255,255,255,.25)}

/* ── Alert ── */
.dsync-alert{border-radius:8px;padding:10px 14px;font-size:12px;font-weight:600;margin-bottom:20px;display:flex;align-items:center;gap:8px}
.dsync-info{background:#eff6ff;border:1px solid #bfdbfe;color:#1d4ed8}
.dsync-warn{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412}
.dsync-danger{background:#fff1f2;border:1px solid #fecdd3;color:#9f1239}

/* ── Section headers ── */
.dsync-section{font-size:11px;font-weight:800;color:#401090;border-bottom:2px solid #e2e8f0;margin:28px 0 14px;padding-bottom:8px;text-transform:uppercase;letter-spacing:1px;display:flex;align-items:center;gap:7px}
.dsync-section-icon{display:inline-flex;align-items:center;opacity:.7}

/* ── KPI Cards ── */
.dsync-grid{display:grid;gap:14px}
.dsync-grid-4{grid-template-columns:repeat(4,1fr)}
.dsync-grid-3{grid-template-columns:repeat(3,1fr)}
.dsync-grid-2{grid-template-columns:repeat(2,1fr)}

.dsync-kpi-card{position:relative;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px 18px 14px;overflow:hidden;transition:all .2s}
.dsync-kpi-card:hover{border-color:#c7d2fe;transform:translateY(-2px);box-shadow:0 4px 16px rgba(0,0,0,.06)}
.dsync-kpi-accent{position:absolute;top:0;left:0;right:0;height:3px;background:var(--ka);}
.dsync-kpi-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:4px}
.dsync-kpi-label{font-size:12px;font-weight:700;color:#475569;margin-bottom:8px}
.dsync-kpi-value{min-height:36px;margin-bottom:4px}
.dsync-big-num{font-size:28px;font-weight:900;line-height:1;color:var(--ka);display:block}
.dsync-kpi-delta{min-height:18px;margin-bottom:6px}
.dsync-kpi-meta{font-size:11px;color:#94a3b8;line-height:1.4;margin-bottom:8px}
.dsync-shimmer{display:inline-block;width:80px;height:28px;border-radius:6px;background:linear-gradient(110deg,#f1f5f9 25%,#e2e8f0 50%,#f1f5f9 75%);background-size:200% 100%;animation:dsShimmer 1.4s ease-in-out infinite}
.dsync-source-tag{display:inline-block;font-size:9.5px;font-weight:600;letter-spacing:.3px;background:#f1f5f9;color:#64748b;padding:2px 8px;border-radius:20px;font-family:Consolas,'Courier New',monospace}

/* ── Delta indicators ── */
.dsync-delta{font-size:11px;font-weight:700}
.dsync-delta-up{color:#dc2626}
.dsync-delta-dn{color:#059669}
.dsync-kpi-detail{font-size:11px;color:#64748b;font-family:Consolas,'Courier New',monospace}

/* ── Pct colors ── */
.dsync-pct-green{color:#059669 !important}
.dsync-pct-amber{color:#d97706 !important}
.dsync-pct-red{color:#dc2626 !important}

/* ── Panels ── */
.dsync-panel{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px;box-shadow:0 1px 3px rgba(0,0,0,.04)}
.dsync-panel-header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px}
.dsync-panel-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:3px}
.dsync-panel-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-panel-badge{background:#f1f5f9;color:#475569;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;font-family:Consolas,'Courier New',monospace}

/* ── Charts ── */
.dsync-chart{height:160px;margin:4px 0 0}
.dsync-chart svg{width:100%;height:100%;overflow:visible}
.dsync-axis{stroke:#e5e7eb;stroke-width:1}
.dsync-line{fill:none;stroke-width:2.5;stroke-linecap:round}
.dsync-fill{}
.dsync-chart-lbl{fill:#94a3b8;font-size:9.5px;font-family:-apple-system,sans-serif}
.dsync-chart-empty{height:100%;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:12px;background:#fafafa;border-radius:8px}
.dsync-chart-footer{display:flex;align-items:center;justify-content:space-between;margin-top:8px;flex-wrap:wrap;gap:4px}
.dsync-chart-footer span{font-size:11px;color:#94a3b8}

/* ── Metrics panel ── */
.dsync-metrics-panel{}
.dsync-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}
.dsync-metric-item{background:#fafbfc;border:1px solid #e2e8f0;border-radius:10px;padding:14px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:8px}
.dsync-metric-icon{width:36px;height:36px;border-radius:9px;display:flex;align-items:center;justify-content:center}
.dsync-metric-num{font-size:26px;font-weight:900;color:#401090;display:block;line-height:1}
.dsync-metric-label{font-size:11px;color:#64748b;font-weight:600}

/* ── Tables ── */
.dsync-table-card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden}
.dsync-table-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #f1f5f9;background:#fafbfc}
.dsync-table-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:2px}
.dsync-table-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-table-badge{background:#f1f5f9;color:#475569;border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;white-space:nowrap}
.dsync-table-footer{padding:10px 18px;border-top:1px solid #f1f5f9;font-size:10px;color:#94a3b8;font-family:Consolas,'Courier New',monospace}
.dsync table{width:100%;border-collapse:collapse}
.dsync th{background:#f8fafc;color:#475569;padding:9px 14px;font-size:10px;text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid #e2e8f0;white-space:nowrap}
.dsync td{padding:10px 14px;border-bottom:1px solid #f8fafc;font-size:12.5px;color:#334155}
.dsync th:not(:first-child),.dsync td:not(:first-child){text-align:right}
.dsync tr:last-child td{border-bottom:none}
.dsync tbody tr:hover td{background:#fafbff}
.dsync-empty{padding:28px;text-align:center;color:#94a3b8;font-size:12px}
.dsync-tbl-loading{padding:28px;text-align:center}
.dsync-spin{display:inline-block;width:20px;height:20px;border:3px solid #e2e8f0;border-top-color:#401090;border-radius:50%;animation:dsSpin .7s linear infinite}
.dsync-date{color:#475569;font-family:Consolas,'Courier New',monospace;font-size:12px}
.dsync-cust{font-weight:600;color:#1e293b}
.dsync-money{font-family:Consolas,'Courier New',monospace;font-weight:700;color:#1e293b}
.dsync-money-warn{color:#dc2626}
.dsync-badge-type{background:#eff6ff;color:#2563eb;border-radius:20px;padding:2px 8px;font-size:10.5px;font-weight:600}
.dsync-badge-days{border-radius:20px;padding:2px 8px;font-size:10.5px;font-weight:700}
.dsync-badge-ok{background:#f0fdf4;color:#059669}
.dsync-badge-amber{background:#fffbeb;color:#d97706}
.dsync-badge-red{background:#fff1f2;color:#dc2626}

/* ── Footer ── */
.dsync-footer{display:flex;align-items:center;justify-content:space-between;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 18px;margin-top:24px;font-size:11px;color:#64748b;flex-wrap:wrap;gap:8px}

/* ── Animations ── */
@keyframes dsShimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}
@keyframes dsSpin{to{transform:rotate(360deg)}}

@media(max-width:1200px){.dsync-grid-4{grid-template-columns:repeat(2,1fr)}.dsync-metrics{grid-template-columns:repeat(2,1fr)}}
@media(max-width:768px){.dsync{padding:12px}.dsync-header{flex-direction:column;align-items:flex-start}.dsync-grid-4,.dsync-grid-3,.dsync-grid-2{grid-template-columns:1fr}}

script:
(function(){
var root=root_element.querySelector('.dsync');if(!root)return;
var method='cannabis_management.api.daily_sync_dashboards.get_lab_daily_sync_dashboard';
function q(sel){return root.querySelector(sel)}
function qa(sel){return Array.prototype.slice.call(root.querySelectorAll(sel))}
function set(name,val){var els=root.querySelectorAll('[data-kpi="'+name+'"]');els.forEach(function(el){el.innerHTML=val;});}
function money(v){v=parseFloat(v||0);if(Math.abs(v)>=1000000)return '$'+(v/1000000).toFixed(1)+'M';if(Math.abs(v)>=1000)return '$'+(v/1000).toFixed(1)+'K';return '$'+v.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:0})}
function num(v,d){return parseFloat(v||0).toLocaleString(undefined,{maximumFractionDigits:d==null?0:d})}
function pct(v){return num(v,1)+'%'}
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function fmtDate(d){if(!d)return'—';var p=String(d).split(' ')[0].split('-');return p.length===3?p[1]+'/'+p[2]+'/'+p[0]:d}

function delta(v,suffix,invertColor){
  v=parseFloat(v||0);
  var up=v>=0;
  var abs=Math.abs(v);
  // For yields: up is good (green). For COD/AR: up is bad (red). invertColor flips.
  var isGood=invertColor?(up):(!up);
  // Actually for lab yields: up = good = green
  var cls=up?(invertColor?'dsync-delta-dn':'dsync-delta-up'):(invertColor?'dsync-delta-up':'dsync-delta-dn');
  var arrow=up?'▲':'▼';
  return '<span class="dsync-delta '+cls+'">'+(up?arrow+' +':arrow+' -')+num(abs,2)+(suffix||'')+' vs prior day</span>';
}

function avg(rows,key){
  if(!rows||!rows.length)return 0;
  var s=0,c=0;
  rows.forEach(function(r){var v=parseFloat(r[key]||0);if(v>0){s+=v;c++;}});
  return c?s/c:0;
}

function lineChart(el,rows,key,color,opts){
  opts=opts||{};
  if(!el)return;
  rows=rows||[];key=key||'value';
  var vals=rows.map(function(r){return parseFloat(r[key]||0)});
  var max=Math.max.apply(null,vals.concat([0]));
  var min=Math.min.apply(null,vals.concat([0]));
  if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data available for this period</div>';return;}
  var w=620,h=opts.small?120:150,p=24,span=Math.max(max-min,1);
  var pts=vals.map(function(v,i){
    var x=p+(i*(w-2*p)/Math.max(vals.length-1,1));
    var y=h-p-((v-min)/span*(h-2*p));
    return[x,y];
  });
  var d=pts.map(function(pt,i){return(i?'L':'M')+pt[0].toFixed(1)+' '+pt[1].toFixed(1)}).join(' ');
  var area=d+' L '+pts[pts.length-1][0]+' '+(h-p)+' L '+pts[0][0]+' '+(h-p)+' Z';
  // Benchmark line
  var benchLine='';
  if(opts.benchmark&&max>0){
    var by=h-p-((opts.benchmark-min)/span*(h-2*p));
    if(by>=p&&by<=(h-p)){
      benchLine='<line x1="'+p+'" y1="'+by.toFixed(1)+'" x2="'+(w-p)+'" y2="'+by.toFixed(1)+'" stroke="#fbbf24" stroke-width="1.5" stroke-dasharray="5,3" opacity=".7"><title>Benchmark: '+opts.benchmark+'</title></line>';
    }
  }
  var labels='';
  if(rows.length>=2){
    var positions=[0,Math.floor(rows.length/2),rows.length-1];
    positions.forEach(function(i){
      var pt=pts[i];
      var lbl=rows[i]?fmtDate(rows[i].date):'—';
      labels+='<text x="'+pt[0].toFixed(1)+'" y="'+(h-6)+'" text-anchor="middle" class="dsync-chart-lbl">'+esc(lbl)+'</text>';
    });
  }
  var lastPt=pts[pts.length-1];
  var lastVal=vals[vals.length-1];
  var tooltip=rows[rows.length-1]?fmtDate(rows[rows.length-1].date)+': '+num(lastVal,2):'—';
  var gid='cg'+Math.random().toString(36).substr(2,6);
  el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'
    +'<defs><linearGradient id="'+gid+'" x1="0" y1="0" x2="0" y2="1">'
    +'<stop offset="0%" stop-color="'+color+'" stop-opacity="0.2"/>'
    +'<stop offset="100%" stop-color="'+color+'" stop-opacity="0.02"/>'
    +'</linearGradient></defs>'
    +'<path fill="url(#'+gid+')" d="'+area+'"></path>'
    +benchLine
    +'<path class="dsync-line" style="stroke:'+color+'" d="'+d+'"></path>'
    +'<circle cx="'+lastPt[0].toFixed(1)+'" cy="'+lastPt[1].toFixed(1)+'" r="4" fill="'+color+'" stroke="#fff" stroke-width="2"><title>'+esc(tooltip)+'</title></circle>'
    +'<line class="dsync-axis" x1="'+p+'" y1="'+(h-p+4)+'" x2="'+(w-p)+'" y2="'+(h-p+4)+'"></line>'
    +labels+'</svg>';
}

function barChart(el,rows,key,color){
  if(!el)return;
  rows=rows||[];key=key||'value';
  var vals=rows.map(function(r){return parseFloat(r[key]||0)});
  var max=Math.max.apply(null,vals.concat([0]));
  if(!rows.length||max===0){el.innerHTML='<div class="dsync-chart-empty">No data available for this period</div>';return;}
  var w=620,h=150,p=24,bw=(w-2*p)/vals.length*.7;
  var bars=vals.map(function(v,i){
    var x=p+i*(w-2*p)/vals.length+bw*.15;
    var bh=(v/max)*(h-2*p);
    var yt=rows[i]?fmtDate(rows[i].date)+'\n'+num(v,1)+' lbs':'';
    return '<rect fill="'+color+'" x="'+x.toFixed(1)+'" y="'+(h-p-bh).toFixed(1)+'" width="'+bw.toFixed(1)+'" height="'+bh.toFixed(1)+'" rx="3" opacity=".78"><title>'+esc(yt)+'</title></rect>';
  }).join('');
  var labels='';
  var positions=[0,Math.floor(rows.length/2),rows.length-1];
  positions.forEach(function(i){
    if(!rows[i])return;
    var x=p+i*(w-2*p)/vals.length+bw*.15+bw/2;
    labels+='<text x="'+x.toFixed(1)+'" y="'+(h-6)+'" text-anchor="middle" class="dsync-chart-lbl">'+esc(fmtDate(rows[i].date))+'</text>';
  });
  el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none">'+bars+'<line class="dsync-axis" x1="'+p+'" y1="'+(h-p+4)+'" x2="'+(w-p)+'" y2="'+(h-p+4)+'"></line>'+labels+'</svg>';
}

function table(headers,rows){
  if(!rows||!rows.length)return '<div class="dsync-empty">No data found for this period.</div>';
  return '<table><thead><tr>'+headers.map(function(h){return'<th>'+esc(h.label)+'</th>'}).join('')+'</tr></thead>'
    +'<tbody>'+rows.map(function(r){return'<tr>'+headers.map(function(h){return'<td>'+h.f(r)+'</td>'}).join('')+'</tr>'}).join('')+'</tbody></table>';
}

function renderLab(d){
  var p=d.production||{};
  // Yesterday date
  var ydEl=q('#dsync-yesterday-date');
  if(ydEl)ydEl.textContent=d.yesterday?fmtDate(d.yesterday):'';
  // Date ranges
  var start=d.yesterday?(function(){var dt=new Date(d.yesterday);dt.setDate(dt.getDate()-29);return dt.toISOString().slice(0,10);})():'—';
  var dr=start?fmtDate(start)+' – '+fmtDate(d.yesterday):'Last 30 days';
  set('lab_date_range',dr);set('lab_date_range2',dr);set('lab_date_range3',dr);set('lab_date_range4',dr);
  // KPIs
  var lbs=parseFloat(p.lbs_ran||0);
  var lbsCls=lbs>=700?'dsync-pct-green':lbs>=400?'dsync-pct-amber':'dsync-pct-red';
  set('lbs','<span class="dsync-big-num '+lbsCls+'">'+num(lbs,1)+' <span style="font-size:14px;font-weight:600;">lbs</span></span>');
  set('lbs_delta',delta(parseFloat(p.lbs_delta||0),' lbs',true));
  var lb=q('[data-bar="lbs"]');if(lb)lb.style.width=Math.min(lbs/900*100,100)+'%';
  var hash=parseFloat(p.hash_yield_pct||0);
  var hashCls=hash>=20?'dsync-pct-green':hash>=12?'dsync-pct-amber':'dsync-pct-red';
  set('hash_yield','<span class="dsync-big-num '+hashCls+'">'+pct(hash)+'</span>');
  set('hash_delta',delta(parseFloat(p.hash_yield_delta||0),'%',true));
  var hb=q('[data-bar="hash"]');if(hb)hb.style.width=Math.min(hash/20*100,100)+'%';
  var rosin=parseFloat(p.rosin_yield_pct||0);
  var rosinCls=rosin>=70?'dsync-pct-green':rosin>=50?'dsync-pct-amber':'dsync-pct-red';
  set('rosin_yield','<span class="dsync-big-num '+rosinCls+'">'+pct(rosin)+'</span>');
  set('rosin_delta',delta(parseFloat(p.rosin_yield_delta||0),'%',true));
  var rb=q('[data-bar="rosin"]');if(rb)rb.style.width=Math.min(rosin/70*100,100)+'%';
  // Trends
  var trends=d.trends||[];
  lineChart(q('[data-chart="hash"]'),trends,'hash_yield_pct','#d97706',{benchmark:20});
  lineChart(q('[data-chart="rosin"]'),trends,'rosin_yield_pct','#059669',{benchmark:70});
  barChart(q('[data-chart="lbs"]'),trends,'lbs_ran','#401090');
  // Avg badges
  var ha=q('#dsync-hash-avg');if(ha)ha.textContent='Avg: '+pct(avg(trends,'hash_yield_pct'));
  var ra=q('#dsync-rosin-avg');if(ra)ra.textContent='Avg: '+pct(avg(trends,'rosin_yield_pct'));
  var la=q('#dsync-lbs-avg');if(la)la.textContent='Avg: '+num(avg(trends,'lbs_ran'),1)+' lbs';
  // Pending invoices
  var pi=d.pending_invoices||{};
  set('pending_invoices','<span class="dsync-big-num" style="color:#7c3aed">'+num(pi.count)+'</span>');
  lineChart(q('[data-chart="pending"]'),(pi.trend||[]),'value','#7c3aed',{small:true});
  // Discrepancies
  var disc=d.discrepancies||{};
  var cnt=disc.open_count||0;
  var discBadge=q('#dsync-disc-badge');
  if(discBadge){discBadge.textContent=cnt+' open';discBadge.className='dsync-disc-badge '+(cnt>0?'dsync-disc-badge-warn':'dsync-disc-badge-ok');}
  set('disc_alert',cnt+' open discrepancies'+(disc.doctype?' — from '+esc(disc.doctype):' — reconciliation DocType not found'));
  var discEl=q('[data-table="disc"]');
  if(discEl)discEl.innerHTML=table([
    {label:'Item',f:function(r){return'<span class="dsync-cust">'+esc(r.item)+'</span>'}},
    {label:'Status',f:function(r){
      var cls=r.status&&r.status.toLowerCase().indexOf('open')!==-1?'dsync-badge-red':'dsync-badge-amber';
      return'<span class="dsync-badge-days '+cls+'">'+esc(r.status)+'</span>';
    }}
  ],disc.rows);
  // EOD
  var eodEl=q('[data-table="eod"]');
  var eodRows=d.eod_rows||[];
  var eb=q('#dsync-eod-count');if(eb)eb.textContent=eodRows.length+' runs';
  if(eodEl)eodEl.innerHTML=table([
    {label:'Run',f:function(r){return'<span class="dsync-cust">'+esc(r.run)+'</span>'}},
    {label:'Operator',f:function(r){return esc(r.operator||'—')}},
    {label:'Input (lbs)',f:function(r){return'<span class="dsync-money">'+num(r.input_lbs,1)+'</span>'}},
    {label:'Hash %',f:function(r){
      var v=parseFloat(r.hash_pct||0);
      var cls=v>=20?'dsync-pct-green':v>=12?'dsync-pct-amber':'dsync-pct-red';
      return'<span class="'+cls+'" style="font-weight:700">'+pct(v)+'</span>';
    }},
    {label:'Note',f:function(r){return'<span style="color:#94a3b8;font-size:11px">'+esc(r.issue||'—')+'</span>'}}
  ],eodRows);
  // Shipments
  var shipData=d.shipments||{};
  var shipRows=shipData.rows||[];
  var sc=q('#dsync-ship-count');if(sc)sc.textContent=shipRows.length+' shipments';
  var sa=q('#dsync-ship-avg');if(sa)sa.textContent='Avg: '+num(avg(shipData.trend||[],'value'),1)+'/day';
  var shipEl=q('[data-table="shipments"]');
  if(shipEl)shipEl.innerHTML=table([
    {label:'DN #',f:function(r){return'<a class="dsync-link" href="/app/delivery-note/'+esc(r.name)+'" target="_blank">'+esc(r.name)+'</a>'}},
    {label:'Customer',f:function(r){return'<span class="dsync-cust">'+esc(r.customer)+'</span>'}},
    {label:'Items',f:function(r){return num(r.items)}},
    {label:'Qty (lbs)',f:function(r){return'<span class="dsync-money">'+num(r.qty,1)+'</span>'}},
    {label:'Value',f:function(r){return'<span class="dsync-money">'+money(r.value)+'</span>'}}
  ],shipRows);
  barChart(q('[data-chart="shipments"]'),shipData.trend||[],'value','#401090');
}

function load(){
  qa('[data-kpi]').forEach(function(el){
    if(!el.innerHTML||el.innerHTML==='—'||el.innerHTML.indexOf('dsync-shimmer')!==-1){
      el.innerHTML='<span class="dsync-shimmer"></span>';
    }
  });
  frappe.call({
    method:method,
    callback:function(r){var d=r.message||{};renderLab(d);set('last_refresh',new Date().toLocaleTimeString());},
    error:function(){frappe.msgprint('Unable to load Lab Daily Sync data.');}
  });
}

var btn=q('[data-action="refresh"]');
if(btn)btn.addEventListener('click',load);
load();
setInterval(load,30*60*1000);
})();

style:
.dsync{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;max-width:1600px;margin:0 auto;padding:24px;color:#1e293b}.dsync *{box-sizing:border-box}

/* ── Header ── */
.dsync-header{background:linear-gradient(135deg,#401090 0%,#7c3aed 60%,#C060E0 100%);color:#fff;border-radius:12px;padding:20px 24px;display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;gap:16px}
.dsync-header-left{display:flex;align-items:center;gap:16px}
.dsync-header-right{display:flex;flex-direction:column;align-items:flex-end;gap:8px}
.dsync-last-refresh{font-size:11px;color:rgba(255,255,255,.7);font-family:Consolas,'Courier New',monospace}
.dsync-header h2{font-size:20px;margin:0 0 2px;font-weight:800;letter-spacing:-.3px;color:#fff;}
.dsync-header p{margin:0;font-size:11.5px;opacity:.82}
.dsync-eyebrow{font-size:10px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;opacity:.75;margin-bottom:3px}
.dsync-logo{width:48px;height:48px;border-radius:10px;border:1px solid rgba(255,255,255,.3);background:rgba(255,255,255,.15);display:flex;align-items:center;justify-content:center;font-weight:900;font-size:16px;flex-shrink:0}
.dsync-refresh{display:inline-flex;align-items:center;gap:6px;border:1px solid rgba(255,255,255,.4);background:rgba(255,255,255,.15);color:#fff;border-radius:8px;padding:8px 14px;font-size:12px;font-weight:700;cursor:pointer;transition:background .15s}
.dsync-refresh:hover{background:rgba(255,255,255,.25)}

/* ── Alert ── */
.dsync-alert{border-radius:8px;padding:10px 14px;font-size:12px;font-weight:600;margin-bottom:20px;display:flex;align-items:center;gap:8px}
.dsync-info{background:#eff6ff;border:1px solid #bfdbfe;color:#1d4ed8}
.dsync-warn{background:#fff7ed;border:1px solid #fed7aa;color:#9a3412}
.dsync-danger{background:#fff1f2;border:1px solid #fecdd3;color:#9f1239}

/* ── Section headers ── */
.dsync-section{font-size:11px;font-weight:800;color:#401090;border-bottom:2px solid #e2e8f0;margin:28px 0 14px;padding-bottom:8px;text-transform:uppercase;letter-spacing:1px;display:flex;align-items:center;gap:7px}
.dsync-section-icon{display:inline-flex;align-items:center;opacity:.7}

/* ── Grid ── */
.dsync-grid{display:grid;gap:14px}
.dsync-grid-4{grid-template-columns:repeat(4,1fr)}
.dsync-grid-3{grid-template-columns:repeat(3,1fr)}
.dsync-grid-2{grid-template-columns:repeat(2,1fr)}

/* ── KPI Cards ── */
.dsync-kpi-card{position:relative;background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px 18px 14px;overflow:hidden;transition:all .2s}
.dsync-kpi-card:hover{border-color:#c7d2fe;transform:translateY(-2px);box-shadow:0 4px 16px rgba(0,0,0,.06)}
.dsync-kpi-accent{position:absolute;top:0;left:0;right:0;height:3px;background:var(--ka)}
.dsync-kpi-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:4px}
.dsync-kpi-label{font-size:12px;font-weight:700;color:#475569;margin-bottom:8px}
.dsync-kpi-value{min-height:36px;margin-bottom:4px}
.dsync-big-num{font-size:28px;font-weight:900;line-height:1;color:var(--ka,#401090);display:block}
.dsync-kpi-delta{min-height:18px;margin-bottom:10px}
.dsync-shimmer{display:inline-block;width:80px;height:28px;border-radius:6px;background:linear-gradient(110deg,#f1f5f9 25%,#e2e8f0 50%,#f1f5f9 75%);background-size:200% 100%;animation:dsShimmer 1.4s ease-in-out infinite}
.dsync-shimmer-sm{width:50px;height:22px}
.dsync-source-tag{display:inline-block;font-size:9.5px;font-weight:600;letter-spacing:.3px;background:#f1f5f9;color:#64748b;padding:2px 8px;border-radius:20px;font-family:Consolas,'Courier New',monospace}

/* ── Delta ── */
.dsync-delta{font-size:11px;font-weight:700}
.dsync-delta-up{color:#059669}
.dsync-delta-dn{color:#dc2626}

/* ── Pct colors ── */
.dsync-pct-green{color:#059669 !important}
.dsync-pct-amber{color:#d97706 !important}
.dsync-pct-red{color:#dc2626 !important}

/* ── Progress meters ── */
.dsync-meter-wrap{margin-bottom:10px}
.dsync-meter{height:6px;background:#f1f5f9;border-radius:4px;overflow:hidden;margin-bottom:4px}
.dsync-meter span{display:block;height:100%;background:linear-gradient(90deg,#401090,#C060E0);width:0;transition:width .6s cubic-bezier(.4,0,.2,1);border-radius:4px}
.dsync-meter-amber span{background:linear-gradient(90deg,#d97706,#fbbf24)}
.dsync-meter-green span{background:linear-gradient(90deg,#059669,#34d399)}
.dsync-meter-label{font-size:10px;color:#94a3b8}

/* ── Mini KPI card (inline) ── */
.dsync-kpi-card-mini{display:flex;flex-direction:column;align-items:center;text-align:center;gap:2px;flex-shrink:0}
.dsync-mini-label{font-size:10px;color:#94a3b8;font-weight:600;text-transform:uppercase;letter-spacing:.5px}

/* ── Panels ── */
.dsync-panel{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:18px;box-shadow:0 1px 3px rgba(0,0,0,.04)}
.dsync-panel-header{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:12px}
.dsync-panel-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:3px}
.dsync-panel-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-panel-badge{background:#f1f5f9;color:#475569;border-radius:8px;padding:5px 10px;font-size:11px;font-weight:700;white-space:nowrap;flex-shrink:0;font-family:Consolas,'Courier New',monospace}

/* ── Charts ── */
.dsync-chart{height:160px;margin:4px 0 0}
.dsync-chart-sm{height:100px}
.dsync-chart svg{width:100%;height:100%;overflow:visible}
.dsync-axis{stroke:#e5e7eb;stroke-width:1}
.dsync-line{fill:none;stroke-width:2.5;stroke-linecap:round}
.dsync-chart-lbl{fill:#94a3b8;font-size:9.5px;font-family:-apple-system,sans-serif}
.dsync-chart-empty{height:100%;display:flex;align-items:center;justify-content:center;color:#94a3b8;font-size:12px;background:#fafafa;border-radius:8px}
.dsync-chart-footer{display:flex;align-items:center;justify-content:space-between;margin-top:8px;flex-wrap:wrap;gap:4px}
.dsync-chart-footer span{font-size:11px;color:#94a3b8}

/* ── Tables ── */
.dsync-table-card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;overflow:hidden}
.dsync-table-head{display:flex;align-items:center;justify-content:space-between;padding:14px 18px;border-bottom:1px solid #f1f5f9;background:#fafbfc}
.dsync-table-eyebrow{font-size:9.5px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#94a3b8;margin-bottom:2px}
.dsync-table-title{font-size:13px;font-weight:700;color:#1e293b}
.dsync-table-badge{background:#f1f5f9;color:#475569;border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;white-space:nowrap}
.dsync-disc-badge{border-radius:20px;padding:4px 10px;font-size:11px;font-weight:700;white-space:nowrap}
.dsync-disc-badge-warn{background:#fff1f2;color:#dc2626}
.dsync-disc-badge-ok{background:#f0fdf4;color:#059669}
.dsync-table-footer{padding:10px 18px;border-top:1px solid #f1f5f9;font-size:10px;color:#94a3b8;font-family:Consolas,'Courier New',monospace}
.dsync table{width:100%;border-collapse:collapse}
.dsync th{background:#f8fafc;color:#475569;padding:9px 14px;font-size:10px;text-align:left;text-transform:uppercase;letter-spacing:.5px;border-bottom:1.5px solid #e2e8f0;white-space:nowrap}
.dsync td{padding:10px 14px;border-bottom:1px solid #f8fafc;font-size:12.5px;color:#334155}
.dsync th:not(:first-child),.dsync td:not(:first-child){text-align:right}
.dsync tr:last-child td{border-bottom:none}
.dsync tbody tr:hover td{background:#fafbff}
.dsync-empty{padding:28px;text-align:center;color:#94a3b8;font-size:12px}
.dsync-tbl-loading{padding:28px;text-align:center}
.dsync-spin{display:inline-block;width:20px;height:20px;border:3px solid #e2e8f0;border-top-color:#401090;border-radius:50%;animation:dsSpin .7s linear infinite}
.dsync-cust{font-weight:600;color:#1e293b}
.dsync-money{font-family:Consolas,'Courier New',monospace;font-weight:700;color:#1e293b}
.dsync-link{color:#401090;font-weight:700;font-family:Consolas,'Courier New',monospace;font-size:12px;text-decoration:none}
.dsync-link:hover{text-decoration:underline}
.dsync-badge-days{border-radius:20px;padding:2px 8px;font-size:10.5px;font-weight:700}
.dsync-badge-ok{background:#f0fdf4;color:#059669}
.dsync-badge-amber{background:#fffbeb;color:#d97706}
.dsync-badge-red{background:#fff1f2;color:#dc2626}

/* ── Footer ── */
.dsync-footer{display:flex;align-items:center;justify-content:space-between;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px 18px;margin-top:24px;font-size:11px;color:#64748b;flex-wrap:wrap;gap:8px}

/* ── Animations ── */
@keyframes dsShimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}
@keyframes dsSpin{to{transform:rotate(360deg)}}

@media(max-width:1200px){.dsync-grid-3{grid-template-columns:repeat(2,1fr)}}
@media(max-width:900px){.dsync-grid-4,.dsync-grid-2{grid-template-columns:1fr}}
@media(max-width:768px){.dsync{padding:12px}.dsync-header{flex-direction:column;align-items:flex-start}.dsync-grid-3{grid-template-columns:1fr}}

script:
/* =================== DISTRIBUTION HUB JS =================== */
/* Yeh file Frappe/ERPNext "Custom Page" ya "Custom Block" (HTML Block + Script) ke
   andar use hoti hai. Backend python file (api.py) ke whitelisted methods ko
   frappe.call() se hit karke pipeline, manifests, gauge, bins aur shortcuts —
   sab kuch dynamically bharti hai. Koi bhi data yahan hardcoded nahi hai.

   Agar aap Frappe use nahi kar rahe (kisi doosre ERP me REST API hai) to sirf
   "callApi()" function ke andar wala fetch logic replace kar dein — baaki sab same rahega. */

(function () {
  "use strict";

  const APP_MODULE = "your_app.distribution_hub"; // <-- apne app ka naam yahan set karein
  let currentCompany = "Master Touch Manufacturing";

  /* ---------- Generic API wrapper ---------- */
  function callApi(method, args) {
    args = args || {};
    if (window.frappe && frappe.call) {
      // Native Frappe call
      return frappe.call({
        method: `${APP_MODULE}.api.${method}`,
        args: args
      }).then((r) => r.message);
    }
    // Fallback: plain REST call (non-Frappe / custom backend)
    const params = new URLSearchParams(args).toString();
    return fetch(`/api/method/${APP_MODULE}.api.${method}?${params}`, {
      headers: { "X-Frappe-CSRF-Token": window.csrf_token || "" }
    })
      .then((res) => res.json())
      .then((data) => data.message);
  }

  /* ---------- Renderers ---------- */

  function populateCompanyFilter(meta) {
    const sel = document.getElementById("dh-company-filter");
    if (!sel) return;
    sel.innerHTML = `<option value="">All Companies</option>`;
    (meta.companies || []).forEach((c) => {
      const opt = document.createElement("option");
      opt.value = c;
      opt.textContent = c;
      sel.appendChild(opt);
    });
  }

  function renderStagePipeline(data) {
    const bar = document.getElementById("dh-stage-bar");
    bar.innerHTML = "";
    (data.stages || []).forEach((stage, idx) => {
      const col = document.createElement("div");
      col.className = `stage-col stage-${idx + 1}`;
      col.innerHTML = `
        <div class="stg-lbl">${escapeHtml(stage.label)}</div>
        <div class="stg-count">${stage.count}</div>
      `;
      bar.appendChild(col);
    });

    const tbody = document.getElementById("dh-order-tbody");
    tbody.innerHTML = "";
    if (!data.orders || !data.orders.length) {
      tbody.innerHTML = `<tr><td colspan="7" class="dh-loading-row">No orders found.</td></tr>`;
      return;
    }
    data.orders.forEach((o) => {
      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td>${escapeHtml(o.name)}</td>
        <td>${escapeHtml(o.customer)}</td>
        <td>${escapeHtml(o.bill_to || "Same")}</td>
        <td>${escapeHtml(o.pickup_dropoff || "--")}</td>
        <td>${escapeHtml(o.requested || "--")}</td>
        <td>${statusPill(o.stage, stageClass(o.stage))}</td>
        <td>${escapeHtml(o.logistics_status || "--")}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  function renderManifests(rows) {
    const tbody = document.getElementById("dh-manifest-tbody");
    tbody.innerHTML = "";
    if (!rows || !rows.length) {
      tbody.innerHTML = `<tr><td colspan="7" class="dh-loading-row">No manifests found.</td></tr>`;
      return;
    }
    rows.forEach((m) => {
      const tr = document.createElement("tr");
      tr.innerHTML = `
        <td>${escapeHtml(m.manifest_no)}</td>
        <td>${escapeHtml(m.dn_ref)}</td>
        <td>${escapeHtml(m.customer)}</td>
        <td>${m.items_count}</td>
        <td>${escapeHtml(m.weight)}</td>
        <td>${escapeHtml(m.metrc_tag || "--")}</td>
        <td>${statusPill(m.status, manifestClass(m.status))}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  function renderGauge(gauge) {
    const pct = Math.max(0, Math.min(100, gauge.percent || 0));
    document.getElementById("dh-gauge-pct").textContent = `${pct}%`;

    // Map 0-100% onto the semicircle arc (approx sweep from 20,110 to 180,110)
    const angle = Math.PI * (1 - pct / 100); // 180deg (0%) -> 0deg (100%)
    const cx = 100, cy = 110, r = 80;
    const x = cx - r * Math.cos(angle);
    const y = cy - r * Math.sin(angle);
    const largeArc = pct > 50 ? 1 : 0;
    const arcPath = `M 20 110 A 80 80 0 ${largeArc} 1 ${x.toFixed(1)} ${y.toFixed(1)}`;
    const arc = document.getElementById("dh-gauge-arc");
    arc.setAttribute("d", arcPath);

    let color = "var(--ok)";
    if (pct >= 90) color = "var(--bad)";
    else if (pct >= 70) color = "var(--warn)";
    arc.setAttribute("stroke", color);
  }

  function renderBins(bins) {
    const list = document.getElementById("dh-bin-list");
    list.innerHTML = "";
    (bins || []).forEach((b) => {
      const li = document.createElement("li");
      li.className = "qitem";
      let color = "";
      if (b.percent >= 90) color = "color:var(--bad)";
      else if (b.percent >= 70) color = "color:var(--warn)";
      li.innerHTML = `
        <div>
          <div class="qname">${escapeHtml(b.warehouse)}</div>
          <div class="qmeta">${escapeHtml(b.capacity_label)}</div>
        </div>
        <span class="qval" style="${color}">${b.percent}%</span>
      `;
      list.appendChild(li);
    });
  }

  function renderShortcuts(items) {
    const grid = document.getElementById("dh-shortcuts-grid");
    grid.innerHTML = "";
    (items || []).forEach((s) => {
      const div = document.createElement("div");
      div.className = `shortcut ${s.kind}`;
      div.innerHTML = `
        <div class="ic">${escapeHtml(s.icon)}</div>
        <span class="lbl">${escapeHtml(s.label)}</span>
        <span class="sub">${escapeHtml(s.sub)}</span>
        ${s.is_new ? '<span class="newf">NEW</span>' : ""}
      `;
      div.addEventListener("click", () => handleShortcutClick(s));
      grid.appendChild(div);
    });
  }

  function handleShortcutClick(shortcut) {
    if (shortcut.route && window.frappe) {
      frappe.set_route(shortcut.route);
    } else if (shortcut.url) {
      window.location.href = shortcut.url;
    }
  }

  /* ---------- Helpers ---------- */
  function statusPill(label, cls) {
    return `<span class="status-pill ${cls}">${escapeHtml(label)}</span>`;
  }
  function stageClass(stage) {
    const map = {
      "Pending in Sales Pipeline": "pur",
      "Need to Schedule": "warn",
      "Scheduled": "info",
      "Preparing": "info",
      "Prepared": "info",
      "Staged": "pur",
      "Closed Out": "ok"
    };
    return map[stage] || "info";
  }
  function manifestClass(status) {
    const map = { "Picking": "info", "Sealed": "ok", "Delivered": "ok", "Held": "bad" };
    return map[status] || "info";
  }
  function escapeHtml(str) {
    if (str === null || str === undefined) return "";
    return String(str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;");
  }

  /* ---------- Data loaders ---------- */
  function loadAll() {
    callApi("get_meta").then(populateCompanyFilter);
    callApi("get_pipeline", { company: currentCompany }).then(renderStagePipeline);
    callApi("get_manifests", { company: currentCompany }).then(renderManifests);
    callApi("get_storage_gauge").then(renderGauge);
    callApi("get_bin_utilization").then(renderBins);
    callApi("get_shortcuts").then(renderShortcuts);
  }

  /* ---------- Init ---------- */
  function init() {
    const root = document.getElementById("dist-hub-root");
    if (!root) return; // block not on page yet

    // Company filter reloads pipeline + manifests
    const companySelect = document.getElementById("dh-company-filter");
    companySelect.addEventListener("change", (e) => {
      currentCompany = e.target.value;
      callApi("get_pipeline", { company: currentCompany }).then(renderStagePipeline);
      callApi("get_manifests", { company: currentCompany }).then(renderManifests);
    });

    loadAll();

    // Auto-refresh every 2 minutes so gauges/pipeline stay live
    setInterval(loadAll, 120000);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  // Expose for Frappe page script to call manually if needed (e.g. inside a Page's onload)
  window.DistributionHub = { init, loadAll };
})();

