/* =================== DISTRIBUTION HUB CSS =================== */
/* Agar aapke ERP theme me already yeh CSS vars defined hain (ERPNext/Frappe desk theme
   ya kisi bhi design system se) to unko override na karein — yeh file unko use karti hai.
   Agar vars defined nahi hain to neeche wale :root fallback defaults use ho jayenge. */

.dist-hub {
  --brand-purple: #6c4fc9;
  --brand-lavender: #a78bfa;
  --line: #e5e2f0;
  --muted: #8a8599;
  --ok: #22c55e;
  --warn: #f59e0b;
  --bad: #ef4444;
  --info: #3b82f6;
  --pur: #8b5cf6;
  --bg-card: #ffffff;
  --bg-page: #f7f6fb;
  --text: #1f1b2e;

  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: var(--text);
  background: var(--bg-page);
  padding: 20px;
  border-radius: 8px;
}

.dist-hub * { box-sizing: border-box; }

/* ---- Badge (used in section titles) ---- */
.dist-hub .badge {
  background: var(--brand-lavender);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  text-transform: uppercase;
}

/* ---- Body layout (sidebar/header removed — single-column main content) ---- */
.dist-hub .ws-body { display: flex; align-items: flex-start; }
.dist-hub .ws-main { flex: 1; display: flex; flex-direction: column; gap: 18px; min-width: 0; }

/* ---- Section card ---- */
.dist-hub .sec {
  background: var(--bg-card);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 16px;
}
.dist-hub .sec-title { display: flex; align-items: center; gap: 8px; margin-bottom: 10px; flex-wrap: wrap; }
.dist-hub .sec-title .t { font-size: 14px; font-weight: 700; }
.dist-hub .dh-select {
  margin-left: auto;
  font-size: 12px;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 4px 8px;
  background: var(--bg-page);
}

/* ---- Stage bar (pipeline) ---- */
.dist-hub .stage-bar { display: flex; gap: 6px; margin-bottom: 14px; flex-wrap: wrap; }
.dist-hub .stage-col {
  flex: 1;
  min-width: 90px;
  background: var(--bg-page);
  border-radius: 8px;
  padding: 10px 8px;
  text-align: center;
  border-top: 3px solid var(--brand-lavender);
}
.dist-hub .stg-lbl { font-size: 10.5px; color: var(--muted); margin-bottom: 4px; min-height: 26px; }
.dist-hub .stg-count { font-size: 20px; font-weight: 800; color: var(--brand-purple); }
.dist-hub .stage-loading, .dh-loading-row { color: var(--muted); font-size: 12px; font-style: italic; }

/* stage color accents (1-7) */
.dist-hub .stage-1 { border-top-color: #94a3b8; }
.dist-hub .stage-2 { border-top-color: var(--warn); }
.dist-hub .stage-3 { border-top-color: var(--info); }
.dist-hub .stage-4 { border-top-color: var(--pur); }
.dist-hub .stage-5 { border-top-color: #06b6d4; }
.dist-hub .stage-6 { border-top-color: var(--brand-lavender); }
.dist-hub .stage-7 { border-top-color: var(--ok); }

/* ---- Table ---- */
.dist-hub .tbl { width: 100%; border-collapse: collapse; font-size: 12.5px; }
.dist-hub .tbl th {
  text-align: left;
  font-size: 10.5px;
  text-transform: uppercase;
  color: var(--muted);
  border-bottom: 1px solid var(--line);
  padding: 8px 6px;
}
.dist-hub .tbl td { padding: 8px 6px; border-bottom: 1px solid var(--line); }
.dist-hub .tbl tr:hover td { background: var(--bg-page); }

.dist-hub .status-pill {
  font-size: 10.5px;
  font-weight: 700;
  padding: 2px 8px;
  border-radius: 999px;
  display: inline-block;
}
.dist-hub .status-pill.info { background: #dbeafe; color: #1d4ed8; }
.dist-hub .status-pill.warn { background: #fef3c7; color: #b45309; }
.dist-hub .status-pill.ok { background: #dcfce7; color: #15803d; }
.dist-hub .status-pill.pur { background: #ede9fe; color: #6d28d9; }
.dist-hub .status-pill.bad { background: #fee2e2; color: #b91c1c; }

/* ---- Chart row (gauge + bins) ---- */
.dist-hub .chart-row.eq { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; }
.dist-hub .legend { display: flex; gap: 14px; font-size: 10.5px; color: var(--muted); margin-top: 8px; }
.dist-hub .legend .sw { width: 8px; height: 8px; border-radius: 2px; display: inline-block; margin-right: 4px; }
.dist-hub .cap { font-size: 11px; color: var(--muted); }

/* ---- Bin list ---- */
.dist-hub .qlist { list-style: none; margin: 0; padding: 0; }
.dist-hub .qitem {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
}
.dist-hub .qitem:last-child { border-bottom: none; }
.dist-hub .qname { font-size: 13px; font-weight: 600; }
.dist-hub .qmeta { font-size: 11px; color: var(--muted); }
.dist-hub .qval { font-weight: 700; font-size: 13px; }

/* ---- Shortcuts grid ---- */
.dist-hub .shortcuts { display: grid; grid-template-columns: repeat(auto-fill, minmax(140px, 1fr)); gap: 10px; }
.dist-hub .shortcut {
  background: var(--bg-page);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  cursor: pointer;
  position: relative;
  transition: transform .12s ease, box-shadow .12s ease;
}
.dist-hub .shortcut:hover { transform: translateY(-2px); box-shadow: 0 4px 10px rgba(0,0,0,.06); }
.dist-hub .shortcut .ic {
  width: 26px; height: 26px;
  border-radius: 6px;
  background: var(--brand-lavender);
  color: #fff;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; font-weight: 800;
}
.dist-hub .shortcut .lbl { font-size: 12px; font-weight: 700; }
.dist-hub .shortcut .sub { font-size: 10.5px; color: var(--muted); }
.dist-hub .shortcut .newf {
  position: absolute; top: 8px; right: 8px;
  font-size: 8.5px; font-weight: 800; color: #fff;
  background: var(--ok); padding: 1px 5px; border-radius: 4px;
}

/* ---- Responsive ---- */
@media (max-width: 900px) {
  .dist-hub .ws-body { flex-direction: column; }
  .dist-hub .ws-sidebar { width: 100%; position: static; }
  .dist-hub .chart-row.eq { grid-template-columns: 1fr; }
}
